// Normalisierung: nimmt Webhook-JSON ODER eine eingehende Mail und baut
// daraus genau die Felder, die das FlowerTech-Bedarfsformular kennt.
// Alles Unbekannte wird verworfen — kein Durchreichen roher Fremddaten.
const out = [];
for (const item of $input.all()) {
  const j = item.json || {};
  const src = j.body && typeof j.body === 'object' ? j.body : j;

  const pick = (...keys) => {
    for (const k of keys) {
      const v = src[k];
      if (v !== undefined && v !== null && String(v).trim() !== '') return String(v).trim();
    }
    return '';
  };

  // Mail-Eingang: Absender und Text als Ausgangspunkt.
  const fromRaw = pick('from', 'From');
  const mailAddress = (fromRaw.match(/[^<\s]+@[^>\s]+/) || [''])[0];

  const token = pick('token', 'projectToken') || ($env.FT_DEFAULT_TOKEN || '');

  const payload = {
    contactName: pick('name', 'contactName', 'fromName').slice(0, 120),
    contactEmail: (pick('email', 'contactEmail') || mailAddress).toLowerCase().slice(0, 160),
    contactPhone: pick('phone', 'contactPhone').slice(0, 60),
    company: pick('company', 'organisation', 'organization').slice(0, 160),
    deliveryType: /programm|program|app|software|tool/i.test(pick('service', 'deliveryType', 'subject', 'Subject')) ? 'program' : 'website',
    goal: pick('goal', 'message', 'text', 'body', 'snippet').slice(0, 2000),
    features: pick('features'),
    currentSystem: pick('currentSystem', 'website', 'url'),
    budget: pick('budget', 'preis'),
    currentProviderPrice: pick('currentProviderPrice'),
    notes: 'Eingang über n8n: ' + pick('source', 'channel', 'Subject', 'subject').slice(0, 200),
  };

  const valid = !!token && /^[A-Za-z0-9_-]{24,64}$/.test(token)
    && /^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(payload.contactEmail)
    && payload.goal.length >= 10;

  // Stabiler Idempotenz-Schlüssel: derselbe Lead wirkt nur einmal.
  const basis = [token, 'briefing', payload.contactEmail, payload.goal].join('|');
  let hash = 5381;
  for (let i = 0; i < basis.length; i++) hash = ((hash << 5) + hash + basis.charCodeAt(i)) >>> 0;

  out.push({ json: {
    valid,
    reason: valid ? '' : 'Token oder Pflichtangaben fehlen — kein Raten, kein Anlegen.',
    token,
    kind: 'briefing',
    payload,
    idempotencyKey: 'ft_' + hash.toString(36) + '_' + basis.length.toString(36),
  }});
}
return out;

// Ergebnis auswerten. 2xx = gebucht (oder als Duplikat erkannt).
// Alles andere landet bewusst im Fehlerpfad, statt still zu verschwinden.
const out = [];
for (const item of $input.all()) {
  const r = item.json || {};
  const code = r.statusCode || 0;
  const body = r.body || {};
  out.push({ json: {
    ok: code >= 200 && code < 300,
    statusCode: code,
    duplicate: !!body.duplicate,
    submissionId: body.submissionId || null,
    error: body.error || (code >= 400 ? ('HTTP ' + code) : null),
  }});
}
return out;
